/**
 * News feed generated by the simulation's event engine.
 */
import { pct } from '../../core/format.js';
import { pageHead } from '../kit.js';
import { emptyState } from '../dom.js';
import { icon } from '../icons.js';
import { formatMarketDate } from '../../market/calendar.js';
import { companyName } from '../labels.js';
import { isCompanyUnlocked } from '../../market/marketAccess.js';

export function createNewsView(ctx) {
  const { i18n, store, router } = ctx;
  const t = (key, p) => i18n.t(key, p);
  let root;
  let container;

  function template(state) {
    const items = state.market.news
      .slice()
      .reverse()
      .filter((item) => !item.ticker || isCompanyUnlocked(state, item.ticker));
    return `
      <div class="news-page">
        ${pageHead({
          eyebrow: t('news.eyebrow'),
          title: t('news.title'),
          subtitle: t('news.subtitle'),
          actions: `<button class="btn btn--ghost btn--sm" type="button" data-go="/market">${icon('market', { size: 15 })} ${t('nav.market')}</button>`,
        })}
        ${items.length ? `
          <div class="news-feed">
            ${items.map((item) => {
              const company = item.ticker ? companyName(ctx, item.ticker) : '';
              const direction = item.pct >= 0 ? 'up' : 'down';
              const headline = t(`news.template.${item.template}`, {
                company,
                pct: pct(Math.abs(item.pct), i18n.locale, 1, false),
              });
              return `
                <article class="news-item">
                  <div class="news-item__meta">
                    <span class="news-kind news-kind--${item.kind}">${t(`news.kind.${item.kind}`)}</span>
                    <span class="muted">${formatMarketDate(item.day, i18n.locale)}</span>
                  </div>
                  <h3 class="news-item__headline">${headline}</h3>
                  <div class="news-item__foot">
                    ${item.ticker ? `<button class="chip" type="button" data-go="/trade/${item.ticker}">${item.ticker} · ${company}</button>` : ''}
                    <span class="news-impact ${direction}">${pct(item.pct, i18n.locale, 1)}</span>
                  </div>
                </article>`;
            }).join('')}
          </div>` : emptyState(icon('news', { size: 26 }), t('news.emptyTitle'), t('news.emptyText'),
          `<button class="btn btn--primary btn--sm" type="button" data-go="/market">${t('nav.market')}</button>`)}
        <p class="page-footnote">${t('news.disclaimer')}</p>
      </div>`;
  }

  function mount(node) {
    root = node;
    container = document.createElement('div');
    root.appendChild(container);
    container.addEventListener('click', (event) => {
      const go = event.target.closest('[data-go]');
      if (go) router.go(go.dataset.go);
    });
    render(store.get());
  }

  function render(state) {
    if (!container) return;
    container.innerHTML = template(state);
  }

  function destroy() {}

  return { mount, render, destroy };
}
